{
  "source_context": [
    {
      "section": "V1",
      "lyrics": [
        "私 ずっとあなたを見てた",
        "孤独を置いてきたみたい",
        "今宵 月も笑いかける",
        "こっちを向いて",
        "oh, fly me to the star"
      ]
    },
    {
      "section": "V2",
      "lyrics": [
        "気持ち 伝えることできなくて",
        "いろんな人生を浮かべ",
        "演じてみるの あなたの気を惹きたいから",
        "oh, fly me to the star"
      ]
    },
    {
      "section": "C1",
      "lyrics": [
        "二人の鼓動 重ね合わせて",
        "たまに不安になる だって",
        "あなたがいなくなりそうで",
        "輝く目に 私以外映さないで",
        "oh, fly me to the star"
      ]
    },
    {
      "section": "B1",
      "lyrics": [
        "明ける夜を 告げた鳥よ",
        "時計の針を今 止めて",
        "流れ星が そっと朝を滑っていく 零れ落ちて",
        "oh, fly me to the star"
      ]
    },
    {
      "section": "O1",
      "lyrics": [
        "連れてって",
        "oh, fly me to the star"
      ]
    }
  ],
  "section": "B1",
  "phrases": [
    {
      "id": "B1-01",
      "ja": "明ける夜を 告げた鳥よ",
      "budget": {
        "min": 12,
        "max": 12
      },
      "pattern": [
        3,
        3,
        3,
        3
      ]
    },
    {
      "id": "B1-02",
      "ja": "時計の針を今 止めて",
      "budget": {
        "min": 11,
        "max": 11
      },
      "pattern": [
        3,
        3,
        2,
        3
      ]
    },
    {
      "id": "B1-03",
      "ja": "流れ星が そっと朝を滑っていく 零れ落ちて",
      "budget": {
        "min": 22,
        "max": 22
      },
      "pattern": [
        6,
        2,
        3,
        5,
        6
      ]
    },
    {
      "id": "B1-04",
      "ja": "oh, fly me to the star",
      "budget": {
        "min": 6,
        "max": 6
      },
      "pattern": [
        1,
        5
      ]
    }
  ],
  "candidates": [
    {
      "label": "A",
      "phrases": [
        {
          "id": "B1-01",
          "zh": "报晓鸟 你别唱 让夜色 再停留"
        },
        {
          "id": "B1-02",
          "zh": "时针它 慢一点 停在 这一秒"
        },
        {
          "id": "B1-03",
          "zh": "一颗流星悄悄 无声 滑进那 将明的清晨 落成满地碎光"
        },
        {
          "id": "B1-04",
          "zh": "oh 带我飞向星"
        }
      ]
    },
    {
      "label": "B",
      "phrases": [
        {
          "id": "B1-01",
          "zh": "鸟已啼 夜要走 让我把 你看够"
        },
        {
          "id": "B1-02",
          "zh": "把时针 拨回去 一夜 再重来"
        },
        {
          "id": "B1-03",
          "zh": "流星悄悄滑过 黎明 的天边 一闪就坠落 从我指缝溜走"
        },
        {
          "id": "B1-04",
          "zh": "带 我飞去星河"
        }
      ]
    },
    {
      "label": "C",
      "phrases": [
        {
          "id": "B1-01",
          "zh": "黎明宣告夜将尽 鸟儿啊"
        },
        {
          "id": "B1-02",
          "zh": "此刻停住时钟的针吧"
        },
        {
          "id": "B1-03",
          "zh": "流星轻轻滑向晨光 洒落消逝"
        },
        {
          "id": "B1-04",
          "zh": "oh, fly me to the star"
        }
      ]
    },
    {
      "label": "D",
      "phrases": [
        {
          "id": "B1-01",
          "zh": "报晓的鸟 啼破残夜"
        },
        {
          "id": "B1-02",
          "zh": "让时钟的针 停在此刻"
        },
        {
          "id": "B1-03",
          "zh": "流星悄悄 滑向黎明 散落成尘"
        },
        {
          "id": "B1-04",
          "zh": "oh, fly me to the star"
        }
      ]
    },
    {
      "label": "E",
      "phrases": [
        {
          "id": "B1-01",
          "zh": "宣告夜色将尽的鸟啊"
        },
        {
          "id": "B1-02",
          "zh": "此刻让时钟的指针停下"
        },
        {
          "id": "B1-03",
          "zh": "流星悄然划过清晨滑落散开"
        },
        {
          "id": "B1-04",
          "zh": "oh, fly me to the star"
        }
      ]
    },
    {
      "label": "F",
      "phrases": [
        {
          "id": "B1-01",
          "zh": "夜色将尽 鸟儿轻声报晓"
        },
        {
          "id": "B1-02",
          "zh": "时钟的指针 请停下吧"
        },
        {
          "id": "B1-03",
          "zh": "流星划过 悄悄 滑向黎明 散落成碎片"
        },
        {
          "id": "B1-04",
          "zh": "oh 带我飞向星"
        }
      ]
    }
  ]
}

